 "<b style=\"font-size:27px;color:#d84b3f\">Ad hominem</b><br><span style=\"font-size:22px;color:#1a2130\">Atacar a quien habla en vez de a lo que dice.</span>": "<b style=\"font-size:27px;color:#d84b3f\">Ad hominem</b><br><span style=\"font-size:22px;color:#1a2130\">Die Person angreifen statt das, was sie sagt.</span>",
 "<b style=\"font-size:27px;color:#ae7e23\">Generalización apresurada</b><br><span style=\"font-size:22px;color:#1a2130\">De unos pocos casos, saltar a «todos».</span>": "<b style=\"font-size:27px;color:#ae7e23\">Voreilige Verallgemeinerung</b><br><span style=\"font-size:22px;color:#1a2130\">Von wenigen Fällen auf »alle« schließen.</span>",
 "<b style=\"font-size:27px;color:#2f6df0\">Falsa causa</b><br><span style=\"font-size:22px;color:#1a2130\">Si pasó después, creer que fue la causa.</span>": "<b style=\"font-size:27px;color:#2f6df0\">Falsche Ursache</b><br><span style=\"font-size:22px;color:#1a2130\">Weil es danach geschah, es für die Ursache halten.</span>",
 "<b style=\"font-size:27px;color:#2e9e6b\">Autoridad mal usada</b><br><span style=\"font-size:22px;color:#1a2130\">«Lo dijo un famoso» no lo hace verdad.</span>": "<b style=\"font-size:27px;color:#2e9e6b\">Falsches Autoritätsargument</b><br><span style=\"font-size:22px;color:#1a2130\">»Ein Promi hat es gesagt« macht es nicht wahr.</span>",
 "Más trampas frecuentes": "Weitere häufige Fallen",
